/** Whether a link is a video clip (VIDEO_CLIPS) rather than a set. */
export const isClip = (url: string) => { const id = /[?&]v=([\w-]{11})/.exec(url)?.[1] ?? ""; return VIDEO_CLIPS.has(id) || ART_CLIP_IDS.has(id); };
