// ── END more-sets-2026-10-22
/** A place's sets: SoundCloud first where it has any (that player behaves best in the game), then its video sets,
 * then its clips, each clip marked so the game shows it rather than plays it. */
/** A set chosen to lead a place's list, whatever it plays on (asked 2026-10-22). */
/** A set to lead a place's list regardless of kind. Empty since 2026-10-22: Robot Heart's SoundCloud comes first, Lee Burridge's video with the rest (asked). */
export const PINNED_FIRST: Record<string, string> = {};
export const campTracks = (c: SoundCamp): { url: string; title: string; clip?: boolean }[] => {
  if (c.piece) return (ART_MEDIA[c.id]?.videos ?? []).map((v) => ({ ...v, clip: true }));
  const own = c.sets ?? [{ url: c.soundcloud, title: `${c.name} on SoundCloud` }];
  const extra = (MORE_SETS[c.id] ?? []).filter((v) => !own.some((o) => o.url === v.url));
  const all = [...own, ...extra, ...(VIDEOS[c.id] ?? []).filter((v) => !own.some((o) => o.url === v.url) && !extra.some((o) => o.url === v.url))];
  const sc = all.filter((t) => t.url.startsWith("https://soundcloud.com/")), vids = all.filter((t) => !t.url.startsWith("https://soundcloud.com/"));
  const list = [...sc, ...vids.filter((t) => !isClip(t.url)), ...vids.filter((t) => isClip(t.url)).map((t) => ({ ...t, clip: true }))];
  const lead = list.find((t) => t.url === PINNED_FIRST[c.id]);
  return lead ? [lead, ...list.filter((t) => t !== lead)] : list;
};
/** Whether a place only has clips: riding past it shows a video, it doesn't take over the music. */
export const clipsOnly = (c: SoundCamp) => campTracks(c).every((t) => t.clip);
